layers.vertex:
attribute vec3 aO;attribute float aT;attribute vec4 aP;uniform float uTime;varying float vS,vY,vU;varying vec3 vN,vV;
void main(){float u=uTime-aT;if(u<0.||u>4.5){gl_Position=vec4(2.,2.,2.,1.);return;}float s=uv.x,angle=uv.y*6.28318;
float grow=smoothstep(0.,.32,u),fade=1.-smoothstep(3.6,4.5,u),h=aP.y*s,spin=aP.x+s*4.7+sin(u*.8+aP.w)*s*.11;
vec3 C=aO+vec3(cos(spin)*(.10+.14*s),h,sin(spin)*(.10+.14*s));float rad=(.043*(1.-s)+.009)*grow*fade;
vec3 T=normalize(vec3(-sin(spin)*.7,aP.y,cos(spin)*.7)),B=normalize(cross(T,vec3(0.,0.,1.))),N=cross(B,T);
vec3 rn=B*cos(angle)+N*sin(angle),P=C+rn*rad-vec3(0.,(1.-grow)*aP.y,0.);
vS=s;vY=angle;vU=u;vN=rn;vV=normalize(cameraPosition-P);gl_Position=projectionMatrix*viewMatrix*vec4(P,1.);}

layers.fragment:
uniform vec3 uSkill;varying float vS,vY,vU;varying vec3 vN,vV;
void main(){float fade=smoothstep(0.,.12,vU)*(1.-smoothstep(3.6,4.5,vU)),s=vS;
float flow=pow(.5+.5*sin(s*16.-vU*2.+vY),7.);vec3 c=uSkill*(.13+.32*flow)+vec3(.18,.37,.12)*flow*.09;
gl_FragColor=vec4(c*fade*(.9-.5*s),fade*(.68-.28*s));}

layers.vertex:
attribute vec3 aO; attribute float aT, aP; uniform float uTime; varying vec2 vP; varying float vU, vPl;
    void main(){ float u = uTime - aT; if (u < 0. || u > 4.0 + .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 4.0 + .35; vP = position.xy*S; vU = u; vPl = uTime - aP;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }

layers.fragment:
uniform vec3 uA, uB, uC2; varying vec2 vP; varying float vU, vPl;
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p - a, ba = b - a; float h = clamp(dot(pa, ba)/dot(ba, ba), 0., 1.); return length(pa - ba*h); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float R = 4.0, r = length(vP), a = atan(vP.y, vP.x), u = vU;
      float draw = clamp(u/.5, 0., 1.), ang01 = fract(a/6.2832 + .25);
      float drawn = smoothstep(0.,.12,vU);                         // the circle draws itself around once
      float fade = smoothstep(0., .1, u)*(1. - smoothstep(4.0, 4.0 + .45, u));
      float pl = vPl >= 0. && vPl < .45 ? pow(1. - vPl/.45, 1.5) : 0.;                 // admission pulse
      float outer = exp(-pow((r - R)/.02, 2.))*drawn + exp(-pow((r - R)/.2, 2.))*.025;
      float inner = exp(-pow((r - R*.86)/.018, 2.))*.28*drawn + exp(-pow((r - R*.72)/.014, 2.))*.15*drawn;
      // rune band between the two inner rings: small glyphs turning slowly
      float rot = u*.06, ar = a + rot, N = 36., cell = floor(ar/6.2832*N), fa = (fract(ar/6.2832*N) - .5)*6.2832/N;
      vec2 q = vec2(fa*R*.79, r - R*.79)/.13;                                          // glyph space
      float hh = h1(cell + 7.), g = seg(q, vec2(0., -.6), vec2(0., .6));
      g = min(g, seg(q, vec2(0., .6 - .7*hh), vec2(hh > .5 ? .45 : -.45, .2 - .5*hh)));
      if (fract(hh*7.3) > .5) g = min(g, seg(q, vec2(-.3, -.6), vec2(.3, -.6)));
      float runes = exp(-pow(g/.09, 2.))*step(abs(r - R*.79), .09)*drawn*.3;
      // 4 broad sigils inside (cardinal), slowly turning the other way: a circle with an inscribed diamond and a stroke
      float sig = 0.;
      for (int i = 0; i < 4; i++){ float an = float(i)*1.5708 - u*.04 + .785; vec2 c = vec2(cos(an), sin(an))*R*.5;
        vec2 p = (vP - c)/.55; float rr = length(p);
        float s = exp(-pow((rr - .9)/.05, 2.)) + exp(-pow((abs(p.x) + abs(p.y) - .75)/.05, 2.))*.8 + exp(-pow(seg(p, vec2(0., -.6), vec2(0., .6))/.05, 2.))*.6;
        sig += s*smoothstep(1.2, 1., rr); }
      sig *= drawn*.12;
      float centre = smoothstep(R*.35, R*.3, r);                                        // the centre stays open
      float lum = (outer*1.1 + inner + runes + sig*(1. - centre))*(1. + pl);
      vec3 o = (uA*lum + uC2*inner*.3 + uB*(exp(-pow((r - R)/.012, 2.))*drawn*.45 + runes*.15)*(1. + pl))*fade;
      o *= smoothstep(R + .35, R + .2, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }
